import * as M from './model.mjs';
import {PARTS,PURPOSES,EQUIPMENT,PILOT_INFO} from '/content/fitness/pilot/catalog.mjs';
import {icon} from './icons.mjs';
import * as P from './plan-picker.mjs';
import * as U from './experience.mjs';
// 双帧原图按素材台账尺寸展示独立的一帧，保持人体比例。
const imageSheets=new Map();
try{const response=await fetch('/content/fitness/pilot/manifest.json');if(response.ok){const manifest=await response.json();for(const image of manifest.images??[])imageSheets.set(image.exerciseId,image)}}catch{}
const KEY='pocket-fitness-prototype-v1', app=document.querySelector('#app'), modal=document.querySelector('#modal');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let s;try{s=localStorage.getItem(KEY)?U.inspectBackup(JSON.stringify({format:'fitness-prototype-json',version:1,state:JSON.parse(localStorage.getItem(KEY))})).state:M.createDemo()}catch{s=M.emptyState();s.loadError=true}
let ui={page:'today',selected:s.demoToday,part:'',purpose:'',search:'',mine:true,source:'all',planStatus:'active',detailId:null,frame:0,statsDays:7,statsStart:M.dayAdd(s.demoToday,-6),statsEnd:s.demoToday,statsPlan:'',statsPurpose:'strength',statsBy:'part',statsMetric:'days',failOnce:false},stack=[],editor=null,toastTimer;
const all=()=>M.exercises(s),get=id=>M.findExercise(s,id),units=e=>e.unit==='seconds'?'秒':'次',segment=e=>e.purpose==='strength'?'组':'段',dateText=d=>`${Number(d.slice(5,7))}月${Number(d.slice(8,10))}日`,week=d=>['周日','周一','周二','周三','周四','周五','周六'][new Date(`${d}T12:00Z`).getUTCDay()];
const btn=(act,label,cls='secondary',attrs='')=>`<button class="${cls}" data-act="${act}" ${attrs}>${label}</button>`;
const notice=(text,warning=false)=>`<div class="notice${warning?' warning':''}">${icon('info')}<span>${text}</span></div>`;
const empty=(title,text,action='')=>`<div class="empty">${icon('calendar')}<h3>${title}</h3><p>${text}</p>${action}</div>`;
function toast(text,action=''){const el=document.querySelector('#toast');el.innerHTML=`<span>${esc(text)}</span>${action}`;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500)}
function persist(next){if(s?.loadError&&next.loadError)throw Error('原资料读取失败，请先导出原始资料或明确重置，已阻止覆盖');if(ui.failOnce){ui.failOnce=false;throw Error('模拟保存失败，原资料未改变。请重试。')}try{localStorage.setItem(KEY,U.checkStorageState(next))}catch(error){if(error.name==='QuotaExceededError')throw Error('浏览器存储空间不足，原资料已保留。请先导出备份并减少个人图片后重试。');throw error}s=next}
function commit(fn,text='',repaint=true){try{persist(fn(s));if(repaint)render();if(text)toast(text);return true}catch(e){toast(e.message);return false}}
const navigationSession=M.uid(),pickerMemory=new Map();
history.replaceState({fitnessSession:navigationSession,depth:0},'');
history.scrollRestoration='manual';
function restorePage(old){ui=old;render();requestAnimationFrame(()=>window.scrollTo(0,old.scroll??0))}
function nav(page,values={}){clearTimeout(searchTimer);rememberPickerScroll();stack.push({...M.clone(ui),scroll:window.scrollY});ui={...ui,page,...values};history.pushState({fitnessSession:navigationSession,depth:stack.length},'');render();window.scrollTo(0,0)}
function back(){clearTimeout(searchTimer);rememberPickerScroll();if(stack.length){if(history.state?.fitnessSession===navigationSession)history.back();else restorePage(stack.pop())}else tab('today')}
window.addEventListener('popstate',event=>{const depth=event.state?.depth;if(event.state?.fitnessSession===navigationSession&&Number.isInteger(depth)&&depth>=0&&depth<stack.length){const old=stack[depth];stack.length=depth;restorePage(old)}else if(stack.length)restorePage(stack.pop())});
function tab(page){clearTimeout(searchTimer);rememberPickerScroll();stack=[];ui={...ui,page};history.replaceState({fitnessSession:navigationSession,depth:0},'');render();window.scrollTo(0,0)}
const partNames=parts=>parts.map(p=>PARTS[p]).filter(Boolean).join(' · ');
function title(name,sub='',actions=''){return `<section class="pagehead"><div><div class="eyebrow">POCKET TOOLBOX / FITNESS</div><h1>${name}</h1>${sub?`<p>${sub}</p>`:''}</div>${actions}</section>`}
function layout(body){const navs=[['today','home','今日'],['plans','calendar','计划'],['library','dumbbell','动作库'],['stats','chart','统计']];const active=ui.page==='detail'&&ui.detailOrigin==='stats'?'stats':ui.page==='detail'&&ui.detailFromTraining?(ui.detailOrigin==='plan'?'plans':'today'):ui.page==='detail'&&(ui.detailPicker||ui.detailEditor)?'plans':['detail','library-list','search'].includes(ui.page)?'library':['editor','plan','picker'].includes(ui.page)?'plans':ui.page;const buttons=navs.map(([id,i,label])=>btn('tab',`${icon(i)}<span>${label}</span>`,active===id?'active':'',`data-page="${id}"`)).join('');return `<aside class="rail"><div class="logo">${icon('dumbbell')}</div><small>随身工具箱</small><nav>${buttons}</nav><footer>${btn('tab',icon('settings'),'quiet','data-page="manage"')}<small>本地交互原型</small></footer></aside><main><header class="topbar"><div class="breadcrumbs">随身工具箱 <span>/</span> 居家健身</div><div class="inline"><span class="prototype">交互原型 · 演示数据</span>${btn('tab',`${icon('settings')} 管理`,'quiet','data-page="manage"')}</div></header>${editor?.saveError&&!['editor','picker'].includes(ui.page)?`<div class="notice warning">当前填写尚未暂存，刷新前请重试。${btn('retry-draft','重试暂存','secondary')}</div>`:''}${s.loadError?notice('本地资料无法读取，已停止自动恢复。请先导出原始资料或在演示面板明确重置。',true):''}${body}<p class="footer-note">资料仅存此浏览器 · 教学内容为待审样稿</p></main><nav class="mobile-nav" aria-label="工具内部导航">${buttons}</nav>`}
const maps={chest:{view:'front',ids:[4]},back:{view:'back',ids:[12,9]},shoulder:{view:'front',ids:[2]},biceps:{view:'front',ids:[1]},triceps:{view:'back',ids:[5]},forearm:{view:'front',ids:[]},core:{view:'front',ids:[6,14]},glutes:{view:'back',ids:[8]},legs:{view:'front',ids:[10]},calves:{view:'back',ids:[7,15]},full:{view:'front',ids:[]}};
function muscle(part,exercise=null,big=false){let map=maps[part]??{view:'front',ids:[]};if(exercise?.id==='EX-LEG-015')map={view:'back',ids:[11]};if(exercise?.id==='EX-SHO-005')map={view:'front',ids:[]};const label=PARTS[part]??'活动示意';return `<div class="muscle${big?' big':''}" role="img" aria-label="${esc(label)}肌肉区域示意，样稿待审"><img src="/muscles/${map.view}.svg" alt=""><span aria-hidden="true">${map.ids.map(id=>`<img class="layer" src="/muscles/main-${id}.svg" alt="">`).join('')}</span>${!map.ids.length?`<span class="part-mark">${part==='forearm'?'示意图暂缺':part==='shoulder'?'示意图待审':'位置参考'}</span>`:''}</div>`}
function pose(e,frame=1,extra=''){
  const sheet=imageSheets.get(e.id),label=e.custom?'个人图片':frame?(e.unit==='seconds'?'保持姿势':'结束姿势'):'起始姿势';
  const half=sheet?.width/2,visual=e.custom?`<img src="${esc(e.image||'')}" class="single-frame" alt="" loading="lazy">`:sheet?`<svg class="pose-frame" viewBox="0 0 ${half} ${sheet.height}" aria-hidden="true"><svg width="${half}" height="${sheet.height}" viewBox="${frame*half} 0 ${half} ${sheet.height}" overflow="hidden"><image href="${esc(e.image)}" width="${sheet.width}" height="${sheet.height}"></image></svg></svg>`:'';
  return `<div class="pose ${extra}${!visual?' failed':''}" role="img" aria-label="${esc(e.name)}${label}样图">${visual}<span class="fallback">${icon('image')}<br>${e.image?'姿势图暂不可用':'尚无姿势图'}</span></div>`;
}
function teachingGallery(e){
  const labels=e.custom?['个人图片']:['起始姿势',e.unit==='seconds'?'保持姿势':'结束姿势'];
  const current=Math.min(ui.frame,labels.length-1);
  return `<section class="card detail-media" data-gallery data-exercise="${e.id}" data-count="${labels.length}"><div class="teaching-track" role="region" aria-roledescription="图片轮播" aria-label="${esc(e.name)}教学步骤图" ${labels.length>1?'tabindex="0"':''}>${labels.map((label,i)=>`<div class="teaching-slide" role="group" aria-roledescription="步骤图片" aria-label="${i+1} / ${labels.length} · ${label}" aria-hidden="${i!==current}">${pose(e,i)}</div>`).join('')}</div><div class="media-toolbar"><div class="gallery-caption" aria-live="polite" aria-atomic="true"><strong data-frame-label>${labels[current]}</strong><small>${e.custom?'个人图片（单张）':`步骤图 <span data-frame-number>${current+1}</span> / ${labels.length}`}</small></div><div class="gallery-dots" aria-hidden="true">${labels.map((_,i)=>`<span class="${i===current?'active':''}"></span>`).join('')}</div>${e.image?btn('retry-gallery','重试图片','image-retry link',`data-id="${e.id}"`):''}${btn('zoom',icon('image'),'quiet',`data-id="${e.id}" aria-label="放大当前姿势图"`)}</div>${labels.length>1?'<p class="gallery-hint">左右滑动查看下一张 · 电脑也可拖动或使用方向键</p>':''}</section>`;
}
function bindGalleries(root=app){
  for(const gallery of root.querySelectorAll('[data-gallery]')){
    const track=gallery.querySelector('.teaching-track'),slides=[...track.children],count=slides.length;
    let drag=null,scrollTick=0;
    const update=()=>{scrollTick=0;if(!track.isConnected||!track.clientWidth)return;const index=Math.max(0,Math.min(count-1,Math.round(track.scrollLeft/track.clientWidth)));ui.frame=index;slides.forEach((slide,i)=>slide.setAttribute('aria-hidden',String(i!==index)));gallery.querySelector('[data-frame-label]').textContent=slides[index].getAttribute('aria-label').split(' · ')[1];const number=gallery.querySelector('[data-frame-number]');if(number)number.textContent=index+1;gallery.querySelectorAll('.gallery-dots span').forEach((dot,i)=>dot.classList.toggle('active',i===index))};
    const go=index=>track.scrollTo({left:Math.max(0,Math.min(count-1,index))*track.clientWidth,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
    track.scrollLeft=Math.min(ui.frame,count-1)*track.clientWidth;
    track.addEventListener('scroll',()=>{if(!scrollTick)scrollTick=requestAnimationFrame(update)},{passive:true});
    track.addEventListener('keydown',event=>{const index=Math.round(track.scrollLeft/track.clientWidth);if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();go(event.key==='Home'?0:event.key==='End'?count-1:index+(event.key==='ArrowRight'?1:-1))}});
    track.addEventListener('pointerdown',event=>{if(event.pointerType!=='mouse'||event.button!==0||count<2)return;event.preventDefault();drag={x:event.clientX,left:track.scrollLeft};track.setPointerCapture(event.pointerId);track.classList.add('dragging')});
    track.addEventListener('pointermove',event=>{if(drag)track.scrollLeft=drag.left+drag.x-event.clientX});
    const finish=event=>{if(!drag)return;const origin=Math.round(drag.left/track.clientWidth),movement=drag.x-event.clientX,target=Math.abs(movement)>Math.min(65,track.clientWidth*.18)?origin+Math.sign(movement):origin;drag=null;track.classList.remove('dragging');if(track.hasPointerCapture(event.pointerId))track.releasePointerCapture(event.pointerId);go(target)};
    track.addEventListener('pointerup',finish);track.addEventListener('pointercancel',event=>{if(!drag)return;drag=null;track.classList.remove('dragging');go(Math.round(track.scrollLeft/track.clientWidth))});
  }
}

function timeline(selected,planId=''){const days=Array.from({length:9},(_,i)=>M.dayAdd(selected,i-3));return `<section class="card timeline-wrap"><div class="timeline-top"><strong>${selected.slice(0,4)}年${Number(selected.slice(5,7))}月 <span class="muted small">训练日历</span></strong><div class="inline">${btn('jump','选择日期','quiet',planId?`data-plan="${planId}"`:'')}${btn('today','回到今天','quiet')}</div></div><div class="timeline-scroll"><div class="timeline">${days.map(d=>{const schedule=M.schedule(s,d),dayPlan=planId?s.plans.find(p=>p.id===planId)?.days.find(x=>x.date===d):null;const parts=planId?dayPlan?.parts??[]:schedule.parts;const items=planId?dayPlan?.items.filter(i=>i.status==='active')??[]:schedule.items;const records=planId?schedule.actual.filter(e=>e.planId===planId):schedule.actual;const kind=planId?dayPlan?.kind??'unplanned':schedule.kind;const labels=parts.length?parts.slice(0,2).map(p=>PARTS[p]):items.length?[...new Set(items.map(i=>PURPOSES[i.purpose]))].slice(0,2):[kind==='rest'?'休息':'未安排'];return `<button class="day-node ${d===selected?'selected':''} ${records.length?'has-records':''}" data-act="date" data-date="${d}" aria-label="${d} ${labels.join('、')}${d===s.demoToday?' 今天':''}" aria-pressed="${d===selected}"><div class="day-parts">${labels.map(x=>`<span>${x}</span>`).join('')}${parts.length>2?`<span>+${parts.length-2}</span>`:''}</div><div class="axis"><i class="node-dot"></i></div><div class="day-number">${Number(d.slice(5,7))}/${Number(d.slice(8))}</div><div class="day-week">${week(d)}${d===s.demoToday?'<span class="today-label">今天</span>':''}</div><div class="day-count">${records.length?`已记${records.length}${records.every(e=>e.snapshot.purpose==='strength')?'组':'条'}`:kind==='training'?'待训练':''}</div></button>`}).join('')}</div></div></section>`}
function recoveryText(){if(!s.preferences.recoveryEnabled)return '恢复提醒已关闭，训练记录和统计仍保留。';const planned=M.schedule(s,s.demoToday).parts,parts=planned.length?planned:[...new Set(M.activeEvents(s,{purpose:'strength',end:s.demoToday}).slice().reverse().map(event=>event.snapshot.primaryPart))].slice(0,2),facts=U.recoveryFacts(s,parts);return facts.length?facts.slice(0,2).map(({part,event})=>`${PARTS[part]}：${event?'最近记录'+dateText(event.day)+(event.timeSource==='dateOnly'?'（时刻未填）':''):'暂无已记录训练'}`).join('；')+'。可查看记录依据与一般恢复参考。':'尚无力量记录。安排同一部位时，可结合最近训练记录和身体感受考虑恢复间隔。'}

function todayPage(){const now=M.schedule(s,s.demoToday),continuous=M.streak(s),primary=U.todayAction(s,ui.selected,ui.focusItemId);const doneParts=new Set(M.activeEvents(s,{start:s.demoToday,end:s.demoToday,purpose:'strength'}).map(e=>e.snapshot.primaryPart));const count=now.parts.filter(p=>doneParts.has(p)).length;const other=now.items.length?[...new Set(now.items.map(i=>PURPOSES[i.purpose]))].join(' · '):now.kind==='rest'?'今日休息':'今日未安排';return title('今天的训练',`${s.demoToday.replaceAll('-','.')} · ${week(s.demoToday)}　照着安排练，每完成一组就记一下。`,`<div class="inline">${btn('continue',esc(primary.label),'secondary')}${btn('new-plan',`${icon('plus')} 新建计划`,'primary')}</div>`)+timeline(ui.selected)+`${!s.plans.length&&!s.events.length?`<section class="card first-use"><h2>从今天的一次训练开始</h2><p>先选部位和动作，填好目标，做完一组点一下。也可以先浏览动作库。</p><div class="inline">${btn('arrange','安排今天','primary',`data-date="${s.demoToday}"`)}${btn('tab','先看动作库','secondary','data-page="library"')}</div></section>`:''}<section class="summary-row"><button class="card summary-tile navy" data-act="streak-info"><span class="stat-label">${icon('flame')} 连续训练</span><div class="stat-value">${continuous.count}<small>天</small></div><span class="stat-foot">${continuous.anchor===s.demoToday?'截至今天':continuous.count?'截至昨天 · 今日尚未记录':'从下一次训练开始记录'}</span></button><button class="card summary-tile" data-act="parts-info"><span class="stat-label">${icon('dumbbell')} ${now.parts.length?'今日计划部位':now.items.length?'今日活动安排':other}</span><div class="stat-parts">${now.parts.length?partNames(now.parts):other}</div><span class="stat-foot">${now.parts.length?`已练主部位 ${count}/${now.parts.length} · 不代表目标全完成`:now.actual.length?'今天已有活动记录':'按自己的节奏安排'}</span></button><section class="card recovery"><div><h3>${icon('leaf')} 恢复参考</h3><p>${esc(recoveryText())}</p></div>${btn('recovery','查看一般建议与记录依据　›','link')}</section></section><div class="day-heading"><div><h2>${dateText(ui.selected)}${ui.selected===s.demoToday?' · 今天':''}</h2><small class="muted">${ui.selected>s.demoToday?'未来日期 · 仅预览':ui.selected<s.demoToday?'历史日期 · 可明确补记':'每完成一组，手动确认一次'}</small></div>${btn('arrange','安排这一天','quiet',`data-date="${ui.selected}"`)}</div>${dayWorkouts(ui.selected)}`}
function workoutCard(plan,date,item){
 const exercise=get(item.exerciseId)??{...item,image:''},events=M.itemEvents(s,item.id),count=events.length,done=count>=item.targetSets,disabled=plan.status!=='active'||date>s.demoToday||item.status!=='active',focused=ui.focusItemId===item.id;
 if(date===s.demoToday&&ui.focusItemId&&!focused)return `<article class="card workout compact-workout" data-workout="${item.id}"><div><strong>${esc(item.name)}</strong><small>${count}/${item.targetSets}${segment(item)} · ${done?'组数已记完':'尚有剩余'}</small></div>${btn('focus-workout',done?'查看动作':'切到此动作','secondary',`data-item="${item.id}"`)}</article>`;
 const latest=events.at(-1),time=latest?latest.timeSource==='dateOnly'?`最近补记操作：${new Date(latest.recordedAt).toLocaleString('zh-CN')}`:latest.timeSource==='user'?`训练时刻（用户填写）：${new Date(latest.actualAt??latest.recordedAt).toLocaleString('zh-CN')}`:`最近确认：${new Date(latest.recordedAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}`:'完成后手动记录';
 const next=U.remaining(s,date).find(row=>row.item.id!==item.id);
 return `<article class="card workout ${focused?'focused':''}" data-workout="${item.id}"><div class="workout-top"><button class="row-main" data-act="detail" data-id="${item.exerciseId}" data-item="${item.id}">${pose(exercise)}</button><div class="workout-title"><button data-act="detail" data-id="${item.exerciseId}" data-item="${item.id}"><h3>${esc(item.name)}</h3></button><p>${PURPOSES[item.purpose]} · ${item.targetSets}${segment(item)} × ${item.side==='each'?'每侧 ':''}${item.targetValue}${units(item)}</p></div>${btn('item-menu',icon('arrow'),'quiet',`data-plan="${plan.id}" data-date="${date}" data-item="${item.id}" aria-label="${esc(item.name)}安排选项"`)}</div><div class="progressline"><div class="bigcount">${count}<span>/ ${item.targetSets} ${segment(item)}</span></div><span class="tag">${done?'组数已记完':'还剩'+(item.targetSets-count)+segment(item)}</span></div><div class="progressbar"><span style="width:${Math.min(100,count/item.targetSets*100)}%"></span></div><button class="complete ${done?'done':''}" data-act="complete" data-plan="${plan.id}" data-date="${date}" data-item="${item.id}" ${disabled||done?'disabled':''}>${icon(done?'check':'plus')}${done?'目标组数已记录':date<s.demoToday?'补记这个动作':`完成第${count+1}${segment(item)}`}</button><div class="workout-foot"><span>${time}</span><div>${btn('events','组明细','link',`data-item="${item.id}"`)}${btn('undo-last',latest?`撤销第${count}${segment(item)}`:'撤销上一组','link',`data-item="${item.id}" ${latest?'':'disabled'}`)}</div></div>${focused&&done&&next?btn('focus-workout',`下一个动作：${esc(next.item.name)}`,'secondary',`data-item="${next.item.id}"`):''}</article>`;
}

function dayWorkouts(date,onlyPlan=''){const plans=s.plans.filter(p=>p.status==='active'&&(!onlyPlan||p.id===onlyPlan));let body='';for(const p of plans){const d=p.days.find(x=>x.date===date);if(!d||d.kind!=='training')continue;const items=d.items.filter(i=>i.status==='active');if(!items.length)continue;body+=`<div class="plan-label"><span>${esc(p.name)}</span>${btn('plan','查看计划 ›','link',`data-id="${p.id}" data-date="${date}"`)}</div><div class="workouts">${items.map(i=>workoutCard(p,date,i)).join('')}</div>`}const events=M.activeEvents(s,{start:date,end:date,planId:onlyPlan});if(!body){const schedule=M.schedule(s,date);body=empty(schedule.kind==='rest'?'今天安排休息':events.length?'当前无剩余安排':'这一天还没有训练安排',events.length?'已记录的训练仍保留在历史和统计中。':'可以先浏览动作，再为这一天安排训练。',btn('arrange','安排这一天','primary',`data-date="${date}"`))}if(events.length)body+=`<details class="history-group"><summary>这一天的全部有效记录 · ${events.length}条（含归档/停止动作）</summary><section class="card spaced">${eventRows(events.slice().reverse())}</section></details>`;return body}
function eventRows(events){const numbers=new Map(),counts=new Map(),plans=new Map(s.plans.map(plan=>[plan.id,plan.name]));for(const event of M.activeEvents(s)){const n=(counts.get(event.itemId)??0)+1;counts.set(event.itemId,n);numbers.set(event.id,n)}return events.length?events.map(event=>`<div class="record-row"><div class="record-dot">${icon('check')}</div><div class="row-copy"><strong>${esc(event.snapshot.name)} · 第${numbers.get(event.id)??event.ordinal}${segment(event.snapshot)}</strong><small>${event.day} · ${esc(plans.get(event.planId)||'原计划')}<br>${event.timeSource==='dateOnly'?'补记 · 训练时刻未填写':event.timeSource==='user'?'用户填写训练时刻：'+new Date(event.actualAt??event.recordedAt).toLocaleString('zh-CN'):'实时确认'} · ${event.snapshot.side==='each'?`左${event.actual.left??'未填'} / 右${event.actual.right??'未填'}`:event.actual.total==null?'实际值未填写':event.actual.total+units(event.snapshot)}</small></div><div class="record-actions">${btn('actual','实际值','link',`data-id="${event.id}"`)}${btn('record-day','查看这天','link',`data-plan="${event.planId}" data-date="${event.day}"`)}</div></div>`).join(''):empty('还没有记录','完成一组后会在这里显示。')}

function exerciseRow(e,{picker=false,selected=false}={}){const match=M.equipmentMatches(e,s.preferences.equipment);return `<article class="exercise-row ${selected?'selected-row':''}"><button class="row-main inline" data-act="detail" data-id="${e.id}">${muscle(e.primaryPart,e)}${pose(e)}<span class="row-copy"><strong>${esc(e.name)}</strong><small>${e.equipment[0].map(x=>EQUIPMENT[x]??x).join('＋')} · ${e.side==='each'?'每侧 ':''}${units(e)}</small><span class="tag ${match?'':'sand'}">${match?PURPOSES[e.purpose]:'缺少部分器械'}</span></span></button>${picker?`<label class="pick-toggle"><input type="checkbox" data-act="pick" data-id="${e.id}" ${selected?'checked':''} aria-label="选择${esc(e.name)}"></label>`:btn('detail',icon('arrow'),'quiet',`data-id="${e.id}" aria-label="查看${esc(e.name)}"`)}</article>`}
function categoryExercises(part,purpose='',secondary=false){return all().filter(exercise=>!exercise.archived&&(!part||exercise.primaryPart===part||secondary&&exercise.secondaryParts.includes(part))&&(!purpose||exercise.purpose===purpose))}

function libraryPage(){const categories=Object.entries(PARTS).map(([key,label])=>`<button class="category" data-act="category" data-id="${key}">${muscle(key)}<strong>${label}</strong><small>${categoryExercises(key).length}个主练动作</small></button>`).join(''),activities=Object.entries(PURPOSES).filter(([key])=>key!=='strength').map(([key,label])=>`<button class="category activity-category" data-act="library-purpose" data-id="${key}"><span class="activity-icon">${icon(key==='cardio'?'flame':key==='warmup'?'dumbbell':'leaf')}</span><strong>${label}</strong><small>${categoryExercises('',key).length}个动作</small></button>`).join('');return title('动作库','按主要训练部位找动作，也可直接搜索名称。',`<div class="inline">${btn('global-search',icon('search'),'secondary','aria-label="全库搜索"')}${btn('custom','新建我的动作','primary')}</div>`)+`<div class="section-title"><small>16个内置样稿 · 250个候选建设池</small>${btn('source','内容与审核状态 ›','link')}</div><section class="categories" aria-label="按训练部位分类">${categories}</section><div class="section-title spaced"><h2>活动分类</h2></div><section class="activity-categories">${activities}</section><div class="section-title spaced"><h2>我的快捷入口</h2></div><div class="quick-links">${btn('global-search',`${icon('check')} 收藏 · ${(s.favorites??[]).filter(id=>get(id)&&!get(id).archived).length}`,'secondary','data-mode="favorites"')}${btn('global-search',`${icon('clock')} 最近练过`,'secondary','data-mode="recent"')}</div>`}

function libraryListPage(){const searchPage=ui.page==='search',mode=ui.searchMode??'all',label=searchPage?(mode==='favorites'?'我的收藏':mode==='recent'?'最近练过':'全库搜索'):ui.part?PARTS[ui.part]+'动作':PURPOSES[ui.purpose]+'动作',ids=mode==='favorites'?s.favorites??[]:mode==='recent'?U.recentExercises(s):null;let scope=searchPage?categoryExercises(''):categoryExercises(ui.part,ui.libraryKind==='purpose'?ui.purpose:'',ui.includeSecondary);if(searchPage&&ids)scope=ids.map(id=>scope.find(exercise=>exercise.id===id)).filter(Boolean);const visible=scope.filter(exercise=>searchPage||!ui.purpose||exercise.purpose===ui.purpose).filter(exercise=>!ui.mine||M.equipmentMatches(exercise,s.preferences.equipment)).filter(exercise=>ui.source==='all'||(ui.source==='custom'?exercise.custom:!exercise.custom)).filter(exercise=>`${exercise.name} ${exercise.english} ${exercise.aliases.join(' ')}`.toLowerCase().includes(ui.search.toLowerCase().trim())),showList=!searchPage||mode!=='all'||ui.search.trim(),shown=showList?visible.slice(0,ui.libraryLimit??20):[];return title(label,searchPage?'搜索当前内容库中的动作、别名或英文名。':'默认按主练部位归类，辅助参与可单独查看。',btn('back',`${icon('back')} 返回分类`,'secondary'))+`${!searchPage&&ui.part?`<div class="inline">${btn('include-secondary',ui.includeSecondary?'已包含辅助参与':'也看辅助参与',`chip ${ui.includeSecondary?'active':''}`,'aria-pressed="'+!!ui.includeSecondary+'"')}</div>`:''}<div class="filters"><label class="search">${icon('search')}<input id="library-search" type="search" aria-label="${searchPage?'全库动作搜索':'搜索当前分类动作'}" placeholder="搜索动作、别名或英文名" value="${esc(ui.search)}"></label><select id="equipment-filter" aria-label="器械匹配"><option value="mine" ${ui.mine?'selected':''}>只看我的器械</option><option value="all" ${!ui.mine?'selected':''}>查看全部器械</option></select><select id="source-filter" aria-label="动作来源">${[['all','内置＋自建'],['custom','我的动作'],['builtin','内置样稿']].map(([key,label])=>`<option value="${key}" ${ui.source===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="section-title"><small>${showList?`当前${visible.length}/${scope.length}个动作 · 已显示${shown.length}个`:'输入名称，搜索全部动作'}</small>${btn('clear-filters','重置筛选','link')}</div><section class="library-list">${shown.map(exercise=>exerciseRow(exercise)).join('')}</section>${!shown.length?empty(showList?'没有匹配动作':'输入动作名称','可以调整器械范围、搜索全库，或创建自己的动作。',`<div class="inline">${!searchPage&&ui.search?btn('global-search','在全库搜索此名称','primary','data-query="'+esc(ui.search)+'"'):''}${btn('library-all-equipment','查看全部器械','secondary')}${btn('custom','新建我的动作','secondary')}</div>`):''}${showList&&shown.length<visible.length?`<div class="load-more">${btn('library-more','加载更多','secondary')}</div>`:''}`}

function detailPage(){const e=get(ui.detailId);if(!e)return title('教学内容暂不可用')+empty('动作定义未找到','历史记录仍按当时快照保留。',btn('back','返回','primary'));return title(esc(e.name),`${esc(e.english||'我的动作')} · ${PURPOSES[e.purpose]}`,btn('back',`${icon('back')} 返回`,'secondary'))+`<div class="inline" style="margin-bottom:16px">${btn('favorite',(s.favorites??[]).includes(e.id)?'已收藏':'收藏动作','secondary',`data-id="${e.id}" aria-pressed="${(s.favorites??[]).includes(e.id)}"`)}<span class="tag">${e.side==='each'?'每侧 ':''}${units(e)}</span><span class="tag gray">${e.equipment[0].map(x=>EQUIPMENT[x]??x).join('＋')}</span><span class="intro-pill">内容样稿 · 待专业审校</span></div><div class="detail-grid">${teachingGallery(e)}<div><section class="card detail-intro"><h2>这个动作是什么</h2><p>${esc(e.intro)}</p><div class="anatomy-panel">${muscle(e.primaryPart,e,true)}<div class="anatomy-copy"><span class="muted">${e.purpose==='strength'?'主要训练部位':'活动用途'}</span><strong>${PARTS[e.primaryPart]??PURPOSES[e.purpose]}</strong><span class="muted">教学参与参考</span><br>${partNames(e.secondaryParts)||'未标注辅助区域'}<p class="muted small">示意图与细分肌群待审；参与标签不重复累计组数。</p></div></div></section></div></div><div class="detail-grid spaced"><section class="card"><h2 style="margin-bottom:19px">准备 → 动作 → 还原</h2><ol class="steps">${e.steps.map((t,i)=>`<li><span class="step-number">${i+1}</span><p>${esc(t)}</p></li>`).join('')}</ol></section><section class="card"><h2 style="margin-bottom:15px">留意这些细节</h2>${e.cues.map(t=>notice(esc(t))).join('')}<small class="muted">没有合格动图时显示静态关键帧，不模拟自动计组或动作识别。</small></section></div><details class="card spaced"><summary>内容来源与版本</summary><p class="small muted spaced">${esc(e.source)}<br>版本：${esc(e.contentRevision)}</p><p class="source-links spaced">${e.references.map(url=>`<a href="${esc(url)}" target="_blank" rel="noreferrer">${esc(url)}</a>`).join('<br>')}</p></details><div class="detail-bottom"><div class="inline"><small class="muted">查看教学后可返回原来的训练。</small>${!e.custom?btn('copy-custom','复制为我的动作','secondary',`data-id="${e.id}"`):''}</div>${ui.detailOrigin==='stats'?btn('back','返回统计','primary'):ui.detailEditor?btn('back','返回动作清单','primary'):ui.detailPicker?btn('pick-detail',P.activeItems(currentEditorDay()).some(item=>item.exerciseId===e.id)?'已选择 · 返回选择页':'加入所选日期','primary',`data-id="${e.id}"`):ui.detailFromTraining?btn('back','返回训练','primary'):btn('add-to-plan','加入我的计划','primary',`data-id="${e.id}"`)}</div>`}
function plansPage(){const list=s.plans.filter(plan=>plan.status===ui.planStatus),draft=editor?.saveError?editor:s.editorDraft;return title('我的训练计划','继续今天，或为接下来的日子安排训练。',btn('new-plan',`${icon('plus')} 新建计划`,'primary'))+`<div class="chips spaced">${[['active','生效计划'],['draft','草稿'],['archived','归档']].map(([id,label])=>btn('plan-filter',label,`chip ${ui.planStatus===id?'active':''}`,`data-id="${id}"`)).join('')}</div>${draft?`<div class="notice spaced"><div class="row-copy"><strong>未提交草稿：${esc(draft.plan.name||'未命名计划')}</strong><small>${draft.plan.start} — ${draft.plan.end} · ${draft.saveError?'暂存失败，当前填写仍在':'不会改变已生效安排'}</small></div>${btn('resume-draft','继续填写','link')}${btn('discard-draft','放弃','quiet')}</div>`:''}<div class="plan-grid spaced">${list.map(plan=>{const records=M.activeEvents(s,{planId:plan.id}),pending=U.remaining(s).filter(row=>row.planId===plan.id),next=plan.days.filter(day=>day.date>=s.demoToday&&day.kind==='training'&&P.activeItems(day).length).sort((a,b)=>a.date.localeCompare(b.date))[0],date=pending.length?s.demoToday:next?.date??records.at(-1)?.day??plan.end,label=plan.status==='archived'?'回看安排与记录':pending.length?'继续今天':next?'查看下一次训练':'回看记录';return `<section class="card plan-card"><span class="tag">${plan.status==='archived'?'已归档':plan.start>s.demoToday?'尚未开始':plan.end<s.demoToday?'日期已结束':'进行中'}</span><h3>${esc(plan.name)}</h3><div class="date">${plan.start} — ${plan.end}</div><div class="counts"><span>${plan.days.filter(day=>day.kind==='training').length}训练日</span><span>${plan.days.filter(day=>day.kind==='rest').length}休息日</span><span>${records.length}条记录</span></div><div class="card-actions">${btn('plan',label,'primary',`data-id="${plan.id}" data-date="${date}"`)}${plan.status==='active'?btn('edit-plan','编辑','secondary',`data-id="${plan.id}"`):''}<details class="plan-more"><summary>更多操作</summary><div class="inline">${btn('archive',plan.status==='archived'?'取消归档':'归档','quiet',`data-id="${plan.id}"`)}${btn('delete-plan','彻底删除','danger',`data-id="${plan.id}"`)}</div></details></div></section>`}).join('')}</div>${!list.length?empty(ui.planStatus==='draft'&&draft?'草稿在上方继续填写':'暂无此类计划','可以先安排今天。',btn('new-plan','创建计划','primary')):''}`}

function planPage(){const plan=s.plans.find(plan=>plan.id===ui.planId);if(!plan)return title('计划不存在')+btn('back','返回');const day=plan.days.find(day=>day.date===ui.selected);return title(esc(plan.name),`${plan.start} — ${plan.end}`,btn('back',`${icon('back')} 返回`))+timeline(ui.selected,plan.id)+(plan.status==='archived'?notice('已归档 · 原安排和实际记录分别保留，可作为新安排的参考。'):notice(`正在查看${ui.selected} · ${day?partNames(day.parts)||({rest:'休息日',unplanned:'未安排'}[day.kind]??'活动安排'):'该日不在计划内'}`))+`<div class="inline spaced">${plan.status==='active'?btn('edit-plan',`编辑${dateText(ui.selected)}安排`,'secondary',`data-id="${plan.id}"`):btn('archive','取消归档','secondary',`data-id="${plan.id}"`)}${plan.status==='active'?btn('edit-plan-info','编辑计划信息','quiet',`data-id="${plan.id}"`):''}${btn('copy-day',plan.status==='archived'?'用原安排创建新安排':'复制这一天','secondary')}${plan.status==='active'&&plan.days.some(day=>day.date===s.demoToday&&P.activeItems(day).length)?btn('plan-today','去今天训练','primary'):''}${plan.status==='active'&&plan.start>s.demoToday?`<span class="muted small">下次训练：${plan.days.find(day=>day.date>=s.demoToday&&P.activeItems(day).length)?.date??'尚未安排'}</span>`:''}</div><div class="spaced">${plan.status==='archived'?readOnlyDay(plan,day):dayWorkouts(ui.selected,plan.id)}</div>`}

function statsPage(){const options={start:ui.statsStart,end:ui.statsEnd,planId:ui.statsPlan};const overview=M.summary(s,options),data=M.summary(s,{...options,purpose:ui.statsPurpose,by:ui.statsBy==='exercise'?'exercise':'part'});data.rows.sort((a,b)=>b[ui.statsMetric]-a[ui.statsMetric]);const max=Math.max(1,...data.rows.map(x=>x[ui.statsMetric]));return title('训练统计','看看过去的记录，也找到接下来的节奏。')+`<div class="inline">${[7,30].map(n=>btn('stats-range',`近${n}天`,`chip ${ui.statsDays===n?'active':''}`,`data-days="${n}"`)).join('')}${btn('custom-range','自定义',`chip ${ui.statsDays===0?'active':''}`)}<span class="muted small">${ui.statsStart.replaceAll('-','.')} — ${ui.statsEnd.replaceAll('-','.')}</span></div><div class="filters"><select id="stats-plan" aria-label="统计计划范围"><option value="">全部计划（包含归档）</option>${s.plans.filter(p=>p.status!=='draft').map(p=>`<option value="${p.id}" ${ui.statsPlan===p.id?'selected':''}>${esc(p.name)}${p.status==='archived'?' · 归档':''}</option>`).join('')}</select><small class="muted">日期和计划作用于全页；下方用途仅筛选训练明细</small></div><h2 class="spaced">本期概览 · 全部用途</h2><section class="stats-overview">${[['训练天数',overview.days,'天'],['力量完成组数',overview.sets,'组'],['记录动作',overview.actions,'个'],['有氧记录',overview.cardio,'段']].map(([label,n,u])=>`<div class="card"><small>${label}</small><strong>${n}<small> ${u}</small></strong></div>`).join('')}</section><div class="stats-layout"><section class="card"><div class="section-title"><h2>${PURPOSES[ui.statsPurpose]}明细 · ${ui.statsBy==='exercise'?'动作':'部位'}</h2>${icon('chart')}</div><div class="chips">${btn('stats-by','部位统计',`chip ${ui.statsBy==='part'?'active':''}`,'data-by="part"')}${btn('stats-by','动作统计',`chip ${ui.statsBy==='exercise'?'active':''}`,'data-by="exercise"')}${btn('stats-by','每日记录',`chip ${ui.statsBy==='daily'?'active':''}`,'data-by="daily"')}</div><div class="filters"><select id="stats-purpose" aria-label="榜单用途">${Object.entries(PURPOSES).map(([k,l])=>`<option value="${k}" ${ui.statsPurpose===k?'selected':''}>${l}</option>`).join('')}</select><select id="stats-metric" aria-label="榜单指标"><option value="days" ${ui.statsMetric==='days'?'selected':''}>训练/活动天次</option><option value="sets" ${ui.statsMetric==='sets'?'selected':''}>完成组/段数</option></select></div>${ui.statsBy==='daily'?eventRows(M.activeEvents(s,{...options,purpose:ui.statsPurpose}).slice().reverse()):data.rows.map(r=>`<button class="bar-row" data-act="stat-detail" data-key="${esc(r.key)}" data-unit="${r.unit}" data-side="${r.side}"><span class="bar-label"><strong>${esc(r.label)}</strong><small>${r.days} 天次 · ${r.sets} ${ui.statsPurpose==='strength'?'组':'段'}</small></span><span class="bar-track"><span class="bar-fill" style="width:${r[ui.statsMetric]/max*100}%"></span></span></button>`).join('')||empty('此范围暂无记录','保存的计划目标不会自动计入实际训练。')}${notice('同一天可练多个部位，各部位天次不能相加成总训练天数。辅助参与不会重复累计主要组数。')}</section><section class="card"><h2>次数与时长</h2><p class="muted small spaced">只统计你主动填写的实际值，未填写不当成0，也不使用目标次数推算。</p>${M.summary(s,{...options,purpose:ui.statsPurpose,by:'exercise'}).rows.map(r=>`<div class="record-row"><div class="row-copy"><strong>${esc(r.label)}</strong><small>${r.side==='each'?`左 ${r.leftFilled?r.left:'未填'} / 右 ${r.rightFilled?r.right:'未填'} ${r.unit==='seconds'?'秒':'次'}<br>共${r.sets}条记录 · 左侧已填${r.leftFilled}条，右侧已填${r.rightFilled}条`:r.filled?`已填写 ${r.actual} ${r.unit==='seconds'?'秒':'次'} · ${r.sets}${ui.statsPurpose==='strength'?'组':'段'}中有${r.filled}${ui.statsPurpose==='strength'?'组':'段'}已填写`:`共${r.sets}条记录，实际值尚未填写`}</small></div><div class="record-actions">${btn('stats-events','查看记录','link',`data-id="${r.key}" data-unit="${r.unit}" data-side="${r.side}" aria-label="查看${esc(r.label)}记录"`)}${btn('detail','教学','link',`data-id="${r.key}" aria-label="查看${esc(r.label)}教学"`)}</div></div>`).join('')||'<p class="muted small spaced">记录一组后，可在组明细补充实际次数或时长。</p>'}</section></div>`}
function managePage(){return title('管理与偏好','个人器械、我的动作和本地资料。',btn('back','返回'))+`<div class="manage-grid"><section class="card"><h2>我的器械</h2><p class="muted small spaced">用于动作筛选，不会删除已有计划。双哑铃可用于单哑铃动作；训练凳、固定点需单独选择。</p><div class="check-grid spaced">${Object.entries(EQUIPMENT).map(([k,l])=>`<label><input type="checkbox" data-equipment="${k}" ${s.preferences.equipment.includes(k)?'checked':''}>${l}</label>`).join('')}</div><div class="section-title spaced"><h3>界面主题</h3></div><div class="chips">${[['fresh','清爽'],['warm','暖白'],['white','纯白']].map(([k,l])=>btn('theme',l,`chip ${s.preferences.theme===k?'active':''}`,`data-theme="${k}"`)).join('')}</div><label class="part-check spaced"><input id="recovery-toggle" type="checkbox" ${s.preferences.recoveryEnabled?'checked':''}>显示恢复参考提醒</label></section><section class="card"><h2>数据与内容</h2><div class="manage-list spaced">${[['custom','edit','新建我的动作','个人动作可没有教学图片，历史按稳定身份保留'],['export','download','导出演示备份','浏览器JSON演示包，包含原型内个人图片'],['import','upload','导入并预检','确认后替换此原型的健身资料'],['source','shield','内容来源与审核状态','肌肉SVG出处、生成图片和待审缺口']].map(([act,i,t,sub])=>`<button class="manage-row" data-act="${act}">${icon(i)}<span class="row-copy"><strong>${t}</strong><small>${sub}</small></span>${icon('arrow')}</button>`).join('')}</div></section></div><section class="card spaced"><div class="section-title"><h2>我的动作 · ${s.customExercises.length}</h2>${btn('custom','新增动作','link')}</div>${s.customExercises.map(e=>`<div class="record-row"><div class="row-copy"><strong>${esc(e.name)} ${e.archived?'<span class="tag gray">已停用</span>':''}</strong><small>${PURPOSES[e.purpose]} · ${e.side==='each'?'每侧 ':''}${units(e)}</small></div>${btn('detail','查看','link',`data-id="${e.id}"`)}${btn('custom','编辑','link',`data-id="${e.id}"`)}${btn('toggle-custom',e.archived?'恢复选择':'停用','link',`data-id="${e.id}"`)}</div>`).join('')||'<p class="muted small">还没有个人动作，可以创建或从内置动作复制。</p>'}</section><section class="demo-panel"><h3>原型演示面板</h3><p class="muted small">以下只用于复现检查场景，不属于正式训练流程。</p><div class="fields spaced"><div class="field"><label for="demo-date">演示中的今天</label><input id="demo-date" type="date" value="${s.demoToday}"></div><div class="field"><label>失败与空状态</label><div class="inline">${btn('fail-next','下一次保存失败','secondary')}${btn('reset-demo','恢复演示数据','secondary')}${btn('reset-empty','空白初次使用','secondary')}</div></div></div><div class="inline">${btn('scenario-cardio','纯有氧日','chip')}${btn('scenario-warmup','仅热身日','chip')}${btn('raw-export','导出原始本地资料','chip')}${btn('source','查看验证范围','chip')}</div></section>`}
function render(){if(['today','plan'].includes(ui.page)&&ui.focusItemId&&!M.schedule(s,ui.selected).plans.some(({plan,day})=>(ui.page!=='plan'||plan.id===ui.planId)&&P.activeItems(day).some(item=>item.id===ui.focusItemId)))ui.focusItemId='';document.body.dataset.theme=s.preferences.theme;document.body.classList.toggle('in-picker',ui.page==='picker');const pages={today:todayPage,library:libraryPage,'library-list':libraryListPage,detail:detailPage,plans:plansPage,plan:planPage,stats:statsPage,manage:managePage,editor:editorPage,picker:pickerPage,search:libraryListPage};app.innerHTML=layout((pages[ui.page]??todayPage)());bindPoseImages();bindGalleries();if(ui.page==='today'||ui.page==='plan')requestAnimationFrame(()=>{const node=app.querySelector('.day-node.selected');const scroller=app.querySelector('.timeline-scroll');if(node&&scroller)scroller.scrollLeft=Math.max(0,node.offsetLeft-scroller.offsetLeft-scroller.clientWidth/2+node.clientWidth/2)})}
function dialog(title,html,onSubmit=null,submitLabel='保存'){const record={dirty:false,save:!!onSubmit,submitting:false};modalState=record;modal.innerHTML=`<div class="modal-heading"><h2 id="modal-title">${title}</h2>${btn('close',icon('close'),'quiet','aria-label="关闭对话框"')}</div><form id="modal-form">${html}<p class="form-error" role="alert" tabindex="-1"></p>${onSubmit?`<div class="modal-actions">${btn('close','取消','secondary')}<button class="primary" type="submit">${submitLabel}</button></div>`:''}</form>`;modal.querySelectorAll('button:not([type])').forEach(button=>button.type='button');modal.querySelector('#modal-form').onsubmit=async event=>{event.preventDefault();if(record.submitting)return;record.submitting=true;const submit=modal.querySelector('button[type=submit]');if(submit)submit.disabled=true;try{await onSubmit?.(new FormData(event.currentTarget))}catch(error){if(modalState===record){modal.querySelector('.form-error').textContent=error.message;modal.querySelector('.form-error').focus()}}finally{record.submitting=false;if(modalState===record&&submit)submit.disabled=false}};if(!modal.open)modal.showModal()}

function confirm(title,text,fn,label='确认'){dialog(title,`<p class="muted">${text}</p>`,()=>{if(fn()!==false)modal.close()},label)}
function field(label,name,type,value,extra=''){return `<div class="field"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
// 编辑器、表单和事件处理在下方，使用同一份模型，不维护第二套展示进度。
let pendingEditorRequest=null,mediaJob=0;
function startEditor(plan=null,date=s.demoToday,options={}){const request={plan,date,...options},draft=editor?.saveError?editor:s.editorDraft,route=U.draftRoute(draft,{planId:plan?.id,source:request.source,date});if(route==='resume'){editor=M.clone(draft);if(request.step!=null)editor.step=request.step;if(editor.plan.days.some(day=>day.date===date))editor.date=date;nav('editor');return}if(route==='protect'){pendingEditorRequest=request;dialog('先处理未完成的草稿',`<p><strong>${esc(draft.plan.name||'未命名计划')}</strong></p><p class="muted small">${draft.plan.start} — ${draft.plan.end}${draft.savedAt?'<br>上次暂存：'+new Date(draft.savedAt).toLocaleString('zh-CN'):''}</p>${notice('继续原草稿可保留当前内容；替换草稿会放弃旧草稿，已生效的计划和记录保留。',true)}<div class="modal-actions">${btn('close','取消','quiet')}${btn('request-replace','替换草稿','danger')}${btn('request-resume','继续原草稿','primary')}</div>`);return}beginEditor(request)}
function beginEditor({plan=null,date=s.demoToday,single=false,source='new',step=0,exerciseId='',sourceDay=null}){const end=single?date:M.dayAdd(date,1),created=plan?M.clone(plan):{id:M.uid(),name:U.defaultName(date,end),start:date,end,status:'draft',days:M.dates(date,end).map(date=>({date,kind:'unplanned',parts:[],items:[]}))};editor={plan:created,editing:!!plan,step,date:created.days.find(day=>day.date===date)?.date??created.days[0].date,entrySource:source,autoName:!plan,pendingExerciseId:exerciseId};if(sourceDay){Object.assign(currentEditorDay(),{kind:'training',parts:[...sourceDay.parts],items:P.activeItems(sourceDay).map(item=>({...M.clone(item),id:M.uid()}))})}if(exerciseId){const exercise=get(exerciseId);if(exercise)M.addItemToDay(currentEditorDay(),exercise,'','')}nav('editor');saveEditorDraft()}
function todayContinue(){const next=U.todayAction(s,ui.selected,ui.focusItemId);if(next.kind==='today'){ui.selected=s.demoToday;render();return}if(next.kind==='continue'){ui.selected=s.demoToday;ui.focusItemId=next.row.item.id;render();document.querySelector(`[data-workout="${next.row.item.id}"]`)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});return}if(next.kind==='arrange'){startEditor(null,s.demoToday,{single:true,source:'day',step:1});return}if(next.kind==='records'){dialog('今天的训练记录',eventRows(M.activeEvents(s,{start:s.demoToday,end:s.demoToday}).reverse()));return}actions.jump()}
async function validatePhotos(state){for(const exercise of state.customExercises.filter(exercise=>exercise.image)){await new Promise((resolve,reject)=>{const photo=new Image();photo.onload=()=>resolve();photo.onerror=()=>reject(Error(`${exercise.name}的个人图片无法读取，请先修复图片；原资料未改变`));photo.src=exercise.image})}}
async function exportDialog(){const job=++mediaJob;dialog('正在检查备份',notice('校验资料结构、个人图片和恢复范围…'));try{const pack=U.prepareBackup(s);await validatePhotos(pack.state);if(job!==mediaJob||!modal.open)return;dialog('备份预检通过',`<div class="inspection">计划${pack.plans}个 · 记录${pack.events}条<br>个人图片${pack.images}张 · 约${(pack.bytes/1024/1024).toFixed(2)} MiB${s.editorDraft?'<br>包含未提交计划草稿':''}</div><p class="muted small spaced">仅包含此原型的健身资料，恢复时替换现有资料。当前JSON备份与导入共用20 MiB上限。</p>`,()=>{download(`fitness-prototype-${s.demoToday}.json`,pack.text);modal.close();toast('已发起下载，请确认备份文件已保存')},'下载备份')}catch(error){if(job===mediaJob&&modal.open)dialog('标准备份暂不可用',`${notice(esc(error.message),true)}<p class="muted small">先保留原始资料，再处理超限或损坏的图片。原始资料导出不承诺可由当前原型恢复。</p>${btn('raw-export','导出原始资料','secondary')}`)}}
async function inspectImport(){const file=modal.querySelector('#backup-file')?.files[0];if(!file)throw Error('请先选择文件');if(file.size>U.MAX_BACKUP_BYTES)throw Error('备份超过20 MiB，当前原型无法完整恢复');const job=++mediaJob,result=U.inspectBackup(await file.text());await validatePhotos(result.state);if(job!==mediaJob||!modal.open)return;dialog('预检通过，确认替换',`<div class="inspection">当前 → 备份<br>计划：${s.plans.length} → ${result.plans}<br>记录：${s.events.length} → ${result.events}<br>个人图片：${s.customExercises.filter(exercise=>exercise.image).length} → ${result.images}<br>约${(result.bytes/1024/1024).toFixed(2)} MiB${s.editorDraft||editor?'<br>当前未提交草稿也会被替换':''}</div>${notice('替换此原型健身资料，建议先下载当前备份；原型未完成正式Android媒体包验证。',true)}`,()=>{if(commit(()=>result.state,'恢复完成，统计已重新计算',false)){editor=null;pendingEditorRequest=null;pickerMemory.clear();ui.selected=s.demoToday;ui.statsEnd=s.demoToday;ui.statsStart=M.dayAdd(s.demoToday,-6);modal.close();tab('today')}},'确认替换')}

function saveEditorDraft(){if(!editor)return false;try{const next=M.clone(s),savedAt=new Date().toISOString();next.editorDraft={...M.clone(editor),savedAt};delete next.editorDraft.saveError;persist(next);editor.saveError=false;editor.savedAt=savedAt;const badge=document.querySelector('#draft-label');if(badge)badge.textContent='草稿已暂存';document.querySelectorAll('[data-act=retry-draft]').forEach(button=>button.remove());return true}catch(e){editor.saveError=true;const badge=document.querySelector('#draft-label');if(badge){badge.textContent='暂存失败，当前填写仍保留';if(!badge.parentElement.querySelector('[data-act=retry-draft]'))badge.insertAdjacentHTML('afterend',btn('retry-draft','重试暂存','link'))}toast(e.message);return false}}
function currentEditorDay(){return editor.plan.days.find(d=>d.date===editor.date)??editor.plan.days[0]}
function editorDays(){if(editor.plan.days.length<=7)return `<div class="date-picks">${editor.plan.days.map(day=>btn('editor-day',`${dateText(day.date)}${day.kind==='rest'?' · 休息':day.kind==='unplanned'?' · 未安排':''}`,day.date===editor.date?'active':'',`data-date="${day.date}"`)).join('')}</div>`;return `<details class="day-overview"><summary>${editor.plan.days.length}天日程 · 训练${editor.plan.days.filter(day=>day.kind==='training').length}天 · 休息${editor.plan.days.filter(day=>day.kind==='rest').length}天 · 未安排${editor.plan.days.filter(day=>day.kind==='unplanned').length}天</summary><div class="date-grid">${editor.plan.days.map(day=>btn('editor-day',`${day.date} · ${day.kind==='training'?partNames(day.parts)||'活动':day.kind==='rest'?'休息':'未安排'}`,day.date===editor.date?'active':'secondary',`data-date="${day.date}"`)).join('')}</div></details><label class="field">当前编辑日期<select id="editor-date-select">${editor.plan.days.map(day=>`<option value="${day.date}" ${day.date===editor.date?'selected':''}>${day.date}</option>`).join('')}</select></label>`}

function editorPage(){if(!editor){editor=s.editorDraft?M.clone(s.editorDraft):null;if(!editor)return title('没有待填写草稿')+btn('new-plan','新建计划')}const p=editor.plan,d=currentEditorDay();let content='';if(editor.step===0)content=`<h2>名称与日期范围</h2><p class="muted small spaced">可以只安排一天，也可以安排一段时间；起止日期都包含。</p><div class="field spaced"><label for="plan-name">计划名称</label><input id="plan-name" data-edit="name" maxlength="60" placeholder="例如：下班后的居家训练" value="${esc(p.name)}"></div><div class="fields"><div class="field"><label for="plan-start">开始日期</label><input id="plan-start" type="date" data-edit="start" value="${p.start}"></div><div class="field"><label for="plan-end">结束日期</label><input id="plan-end" type="date" data-edit="end" value="${p.end}"></div></div>${notice('原型一次最多安排366天。日期变更不会自动搬移已发生的训练记录。')}`;
  if(editor.step===1)content=`<h2>每天想练哪些部位</h2><p class="muted small spaced">先选日期，再选择训练、休息或暂不安排。纯有氧日可以不选肌肉部位。</p><div class="spaced">${editorDays()}</div><div class="day-status">${[['training','训练日'],['rest','休息日'],['unplanned','未安排']].map(([k,l])=>btn('day-kind',l,`chip ${d.kind===k?'active':''}`,`data-kind="${k}"`)).join('')}</div>${d.kind==='training'?`<div class="chips">${Object.entries(PARTS).map(([k,l])=>`<label class="part-check ${d.parts.includes(k)?'checked':''}"><input type="checkbox" data-part="${k}" ${d.parts.includes(k)?'checked':''}>${l}</label>`).join('')}</div>${notice('所选的每个力量部位都需要一个同主归属动作；辅助参与不会自动满足主训练。')}`:`<p class="muted">${d.kind==='rest'?'这一天不安排动作，记录过的历史仍保留。':'这一天尚未安排，保存时会明确保留为空白日。'}</p>`}<div class="inline spaced">${btn('batch-days','批量安排部位','secondary')}${btn('copy-editor-day','复制本日安排到多个日期','secondary')}${btn('wizard-step','下一步选动作','link','data-step="2"')}</div>`;
  if(editor.step===2)content=selectedDayPage(d);
  if(editor.step===3)content=planReview(editor.plan);
  return title(editor.editing?'编辑训练计划':'创建训练计划','一步一步安排，填写过程自动暂存草稿。',btn('leave-editor','暂存并返回','secondary'))+`<div class="editor-layout"><aside class="wizard-steps">${['基础信息','每日部位','动作与目标','预览保存'].map((l,i)=>`<button class="wizard-step ${editor.step===i?'active':''}" data-act="wizard-step" data-step="${i}"><span>${i+1}</span>${l}</button>`).join('')}</aside><section class="card"><span id="draft-label" class="save-badge">${editor.saveError?'暂存失败，当前填写仍保留':'草稿已暂存'}</span>${editor.saveError?btn('retry-draft','重试暂存','link'):''}<div class="spaced">${editor.pendingExerciseId&&editor.plan.days.some(day=>P.activeItems(day).some(item=>item.exerciseId===editor.pendingExerciseId))?notice('已带入动作：'+esc(get(editor.pendingExerciseId)?.name??'所选动作')+'，可继续选择部位和填写目标。'):''}${content}</div><p id="editor-error" class="form-error" role="alert" tabindex="-1"></p><div class="editor-actions">${btn('wizard-prev',editor.step?'上一步':'返回计划','secondary')}<button class="primary" data-act="${editor.step===3?'save-plan':'wizard-next'}" ${editor.step===3&&U.planIssues(editor.plan,s).length?'disabled':''}>${editor.step===3?'保存计划':editor.step===2?'预览计划':'下一步'} ${icon('arrow')}</button></div></section></div>`}
function validateEditorBefore(step){if(step>0){if(!editor.plan.name.trim())throw Error('请填写计划名称');const range=M.dates(editor.plan.start,editor.plan.end);const old=editor.plan.days;editor.plan.days=range.map(date=>old.find(d=>d.date===date)??{date,kind:'unplanned',parts:[],items:[]});for(const d of old)if(!range.includes(d.date)&&s.events.some(e=>e.planId===editor.plan.id&&e.day===d.date))editor.plan.days.push(d);if(!editor.plan.days.some(d=>d.date===editor.date))editor.date=editor.plan.days[0].date}}
function editorStep(step){try{validateEditorBefore(step);editor.step=step;saveEditorDraft();render();window.scrollTo(0,0)}catch(e){const el=document.querySelector('#editor-error');if(el)el.textContent=e.message;toast(e.message)}}
function replaceEditorDay(next){const index=editor.plan.days.findIndex(day=>day.date===editor.date);if(index<0)throw Error('计划日期已经改变，请返回清单');editor.plan.days[index]=next}
function pick(id){if(!editor)return;replaceEditorDay(P.toggleItem(currentEditorDay(),get(id)));saveEditorDraft();repaintPicker()}
function removeEditorItem(id){const next=M.clone(currentEditorDay()),item=next.items.find(item=>item.id===id);if(item)item.status='stopped';replaceEditorDay(next);saveEditorDraft();repaintPicker()}
function groupLabel(key){const [kind,id]=key.split(':');return (kind==='part'?PARTS[id]:PURPOSES[id])??'其他动作'}
function targetRow(item){const group=P.activeItems(currentEditorDay()).filter(entry=>P.groupKey(entry)===P.groupKey(item)),index=group.findIndex(entry=>entry.id===item.id),exercise=get(item.exerciseId)??{...item,image:''};return `<article class="selected-item"><div class="selected-item-head"><button class="row-main inline" data-act="detail" data-id="${item.exerciseId}">${pose(exercise)}<span class="row-copy"><strong>${esc(item.name)}</strong><small>${item.side==='each'?'每侧 · ':''}${units(item)} · 点图片查看教学</small></span></button><div class="selected-item-actions">${btn('reorder','↑','quiet',`data-id="${item.id}" aria-label="上移${esc(item.name)}" data-direction="-1" ${index===0?'disabled':''}`)}${btn('reorder','↓','quiet',`data-id="${item.id}" aria-label="下移${esc(item.name)}" data-direction="1" ${index===group.length-1?'disabled':''}`)}${btn('editor-remove','移除','link',`data-id="${item.id}" aria-label="移除${esc(item.name)}"`)}</div></div><div class="target-controls"><label>${segment(item)}数<input type="number" min="1" max="99" inputmode="numeric" data-target="sets" data-id="${item.id}" value="${esc(item.targetSets)}" placeholder="请填写" aria-label="${esc(item.name)}组段数"></label><label>每${segment(item)}${item.side==='each'?'每侧':''}${item.unit==='seconds'?'时长（秒）':'次数'}<input type="number" min="1" max="${item.unit==='seconds'?3600:999}" inputmode="numeric" data-target="value" data-id="${item.id}" value="${esc(item.targetValue)}" placeholder="请填写" aria-label="${esc(item.name)}每组目标"></label></div></article>`}
function selectedDayPage(day){
  const groups=P.groups(day),items=P.activeItems(day),missing=groups.filter(group=>group.key.startsWith('part:')&&!group.items.length),neighbors=editor.plan.days.filter(other=>[M.dayAdd(day.date,-1),M.dayAdd(day.date,1)].includes(other.date)&&other.kind==='training').map(other=>({date:other.date,parts:other.parts.filter(part=>day.parts.includes(part))})).filter(other=>other.parts.length);
  return `<div class="section-title"><div><h2>当天动作清单</h2><p class="muted small">先按部位添加动作，再统一填写目标。</p></div><span class="tag">${items.length}个已选</span></div>${editorDays()}<div class="selected-day-context"><strong>${day.date} · ${day.kind==='rest'?'休息日':day.kind==='unplanned'?'未安排':partNames(day.parts)||'活动训练'}</strong>${items.length?btn('batch-targets','批量填写目标','link'):''}</div>${neighbors.length?notice('相邻训练日也安排了这些部位：'+neighbors.map(other=>other.date+' '+partNames(other.parts)).join('；')+'。请结合训练负荷与身体感受考虑间隔。'):''}<div class="selection-groups">${groups.map(group=>`<section class="selection-group"><div class="selection-group-heading"><div><h3>${groupLabel(group.key)}</h3><small class="${group.items.length?'muted':'needs-selection'}">${group.items.length?`已选${group.items.length}个动作`:'尚未选择动作'}</small></div>${group.items.length?btn('batch-targets','填写本组目标','link',`data-scope="${group.key}"`):''}</div>${group.items.length?`<details class="selected-group-details" open><summary>已选动作 · ${group.items.length}</summary>${group.items.map(targetRow).join('')}</details>`:'<p class="group-empty">添加动作后，在这里填写组次或时长。</p>'}${btn('open-picker',`${icon('plus')} 添加${groupLabel(group.key)}动作`,'add-group-action',`data-scope="${group.key}"`)}</section>`).join('')}</div>${!day.parts.length?notice('此日期可直接安排有氧、热身或拉伸。若要安排力量训练，先到“每日部位”选择想练的部位。'):''}<div class="activity-additions"><strong>补充活动</strong><div class="chips">${['warmup','cardio','stretch'].map(purpose=>btn('open-picker',`${icon('plus')} ${PURPOSES[purpose]}`,'chip',`data-scope="purpose:${purpose}"`)).join('')}</div></div><div class="day-selection-summary">当天已选${items.length}个动作${missing.length?` · ${missing.map(group=>groupLabel(group.key)).join('、')}待补`:''}</div><div class="inline">${btn('copy-editor-day','复制到多个日期','secondary')}${btn('save-template','保存为个人模板','secondary')}${btn('apply-template','使用个人模板','secondary')}</div>`;
}
function pickerView(){return ui.picker.views[ui.picker.scope]??{query:'',gear:'all',mine:true,source:'all',limit:P.PAGE_SIZE,scroll:0}}
function storePicker(){if(ui.picker)pickerMemory.set(`${ui.picker.planId}|${ui.picker.date}`,M.clone(ui.picker))}
function rememberPickerScroll(){if(ui.page!=='picker'||!ui.picker)return;const view={...pickerView(),scroll:window.scrollY};ui.picker={...ui.picker,views:{...ui.picker.views,[ui.picker.scope]:view}};storePicker()}
function updatePickerView(patch){ui.picker={...ui.picker,views:{...ui.picker.views,[ui.picker.scope]:{...pickerView(),...patch}}};storePicker()}
function repaintPicker(){const scroll=window.scrollY;render();window.scrollTo(0,scroll)}
function openPicker(scope){const day=currentEditorDay(),key=`${editor.plan.id}|${day.date}`,previous=pickerMemory.get(key);nav('picker',{picker:{...(previous??{date:day.date,planId:editor.plan.id,views:{}}),scope:scope??P.scopes(day)[0],view:'all'}});storePicker();requestAnimationFrame(()=>window.scrollTo(0,pickerView().scroll??0))}
function changePickerScope(scope){rememberPickerScroll();ui.picker={...ui.picker,scope,view:'all'};storePicker();render();requestAnimationFrame(()=>window.scrollTo(0,pickerView().scroll??0))}
function setPickerFilter(patch){updatePickerView({...patch,limit:P.PAGE_SIZE,scroll:0});render();window.scrollTo(0,0)}
function pickerPage(){
  if(!editor||editor.plan.id!==ui.picker?.planId||editor.date!==ui.picker.date)return title('选择日期已改变')+empty('请返回计划重新选择日期','已保存的草稿会继续保留。',btn('back','返回','primary'));
  const day=currentEditorDay(),items=P.activeItems(day),view=pickerView(),selected=new Set(items.map(item=>item.exerciseId)),result=P.candidates(all(),s.preferences.equipment,{scope:ui.picker.scope,...view}),selectedView=ui.picker.view==='selected';
  const list=selectedView?P.groups(day).filter(group=>group.items.length).map(group=>`<section class="picker-selected-group"><h2>${groupLabel(group.key)} <span class="tag">${group.items.length}个</span></h2><div class="library-list">${group.items.map(item=>exerciseRow(get(item.exerciseId)??{...item,id:item.exerciseId,image:'',equipment:[['floor']],custom:true},{picker:true,selected:true})).join('')}</div></section>`).join(''):result.items.map(exercise=>exerciseRow(exercise,{picker:true,selected:selected.has(exercise.id)})).join('');
  return title(selectedView?'当天已选动作':`选择${groupLabel(ui.picker.scope)}动作`,`${day.date} · 选择自动暂存，完成后返回填写目标。`,btn('back',`${icon('back')} 返回清单`,'secondary'))+`<div class="picker-sticky"><div class="picker-context"><strong>${dateText(day.date)} · ${selectedView?'所有部位已选':groupLabel(ui.picker.scope)}</strong><small id="draft-label" class="save-badge">${editor.saveError?'暂存失败，当前选择仍保留':'草稿已暂存'}</small></div><div class="scope-strip" aria-label="切换计划部位或活动">${P.scopes(day).map(scope=>{const count=items.filter(item=>P.groupKey(item)===scope).length;return btn('picker-scope',`${groupLabel(scope)} <span>${count}</span>`,`scope-chip ${!selectedView&&ui.picker.scope===scope?'active':''}`,`data-scope="${scope}" aria-pressed="${!selectedView&&ui.picker.scope===scope}"`)}).join('')}</div>${selectedView?'<p class="muted small">这里显示当天全部已选，不受搜索和器械筛选影响。</p>':`<label class="search picker-search">${icon('search')}<input id="picker-search" type="search" aria-label="搜索当前部位动作" placeholder="搜索动作、别名或英文名" value="${esc(view.query)}"></label><div class="chips gear-chips">${[['all','全部器械'],['floor','徒手'],['dumbbell','哑铃'],['band','弹力带']].map(([key,label])=>btn('picker-gear',label,`chip ${view.gear===key?'active':''}`,`data-gear="${key}"`)).join('')}</div><div class="picker-selects"><select id="picker-equipment" aria-label="选择页器械范围"><option value="mine" ${view.mine?'selected':''}>只看我的器械</option><option value="all" ${!view.mine?'selected':''}>查看全部器械</option></select><select id="picker-source" aria-label="选择页动作来源">${[['all','内置＋自建'],['builtin','内置样稿'],['custom','我的动作']].map(([key,label])=>`<option value="${key}" ${view.source===key?'selected':''}>${label}</option>`).join('')}</select></div>`}</div><div class="section-title picker-result-count"><small>${selectedView?`当天共${items.length}个已选动作`:`匹配${result.total}个 · 已显示${result.items.length}个`}</small>${!selectedView?btn('picker-clear','清空筛选','link'):''}</div><div class="${selectedView?'picker-selected-list':'library-list'}">${list}</div>${!(selectedView?items.length:result.total)?empty(selectedView?'还没有选择动作':'没有匹配动作',selectedView?'先选择一个部位或活动，再挑选动作。':'清空筛选或查看全部器械，也可以添加自己的动作。',selectedView?btn('picker-selected','继续挑选','primary'):`<div class="inline">${btn('picker-clear','重置筛选','primary')}${btn('picker-all-equipment','查看全部器械','secondary')}${btn('picker-custom','新建动作并加入当天','secondary')}</div>`):''}${!selectedView&&result.hasMore?`<div class="load-more">${btn('picker-more',`加载更多 · 还有${result.total-result.items.length}个`,'secondary')}</div>`:''}<div class="picker-bottom"><div class="picker-total"><strong>当天已选 <b>${items.length}</b> 个</strong><small>目标回到清单填写</small></div>${btn('picker-selected',selectedView?'继续挑选':'查看已选','secondary')}${btn('back','完成选择','primary')}</div>`;
}
function batchTargetsDialog(scope='all'){
  const day=currentEditorDay(),available=P.groups(day).filter(group=>group.items.length);
  dialog('批量填写目标',`<div class="field"><label for="batch-scope">应用范围</label><select id="batch-scope" name="scope"><option value="all" ${scope==='all'?'selected':''}>当天全部已选动作</option>${available.map(group=>`<option value="${group.key}" ${group.key===scope?'selected':''}>${groupLabel(group.key)} · ${group.items.length}个动作</option>`).join('')}</select></div>${field('组/段数（可选）','sets','number','','min="1" max="99"')}${field('次数类每组次数（可选）','reps','number','','min="1" max="999"')}${field('计时类每组秒数（可选）','seconds','number','','min="1" max="3600"')}<label class="overwrite-option"><input name="overwrite" type="checkbox"> 覆盖已有目标（默认只填空值）</label>${notice('次数和秒数分别填写；每侧动作的目标仍表示每一侧。') }`,form=>{replaceEditorDay(P.batchTargets(currentEditorDay(),{scope:form.get('scope'),sets:form.get('sets'),reps:form.get('reps'),seconds:form.get('seconds'),overwrite:form.get('overwrite')==='on'},s.events));saveEditorDraft();render();modal.close()});
}

function eventsDialog(itemId){const events=M.itemEvents(s,itemId);dialog('已确认组明细',`<p class="muted small">记录目标、真实操作时间和可选实际值分开保存。撤销不会把下一组变成另一动作。</p>${eventRows(events.slice().reverse())}${events.length?btn('undo-last','撤销上一组','danger',`data-item="${itemId}"`):''}`)}
function actualDialog(id){const e=s.events.find(e=>e.id===id);if(!e)return;const each=e.snapshot.side==='each';dialog(`${esc(e.snapshot.name)} · 第${e.ordinal}${segment(e.snapshot)}`,`<p class="muted small">当时目标：${e.snapshot.side==='each'?'每侧':''}${e.snapshot.targetValue}${units(e.snapshot)}。实际值可以低于目标，也可以留空。</p><div class="spaced">${each?`<div class="fields">${field(e.snapshot.unit==='seconds'?'左侧实际时长（秒）':'左侧实际次数','left','number',e.actual.left??'','min="1"')}${field(e.snapshot.unit==='seconds'?'右侧实际时长（秒）':'右侧实际次数','right','number',e.actual.right??'','min="1"')}</div>`:field(e.snapshot.unit==='seconds'?'实际完成时长（秒）':'实际完成次数','total','number',e.actual.total??'','min="1"')}</div>${btn('actual-target','按本组目标填写','secondary',`data-id="${id}"`)} <small class="muted">填入后仍需点保存</small>`,data=>{const values=Object.fromEntries(data);if(commit(old=>M.actualValue(old,id,values),'实际值已保存'))modal.close()})}
let completeGuard={key:'',at:0};
function completeAction(data){if(data.date<s.demoToday){backfillDialog(data);return}const key=data.plan+'|'+data.date+'|'+data.item,now=performance.now();if(completeGuard.key===key&&now-completeGuard.at<650)return;completeGuard={key,at:now};const args={planId:data.plan,day:data.date,itemId:data.item,requestId:M.uid()};if(commit(old=>{const next=M.complete(old,args);next.preferences.lastTrainingItemId=data.item;return next})){const event=s.events.at(-1);toast('已记录：'+event.snapshot.name+'一'+segment(event.snapshot),btn('undo-event','撤销','',`data-id="${event.id}"`))}else completeGuard={key:'',at:0}}
function backfillDialog(data){const {plan,item}=M.locate(s,data.plan,data.date,data.item),remaining=item.targetSets-M.itemEvents(s,item.id).length,batchId=M.uid();dialog('补记过去的训练',`<p><strong>${data.date} · ${esc(item.name)}</strong></p><p class="muted small">${esc(plan.name)} · 还可补记${remaining}${segment(item)}。本次只记录训练日期，具体时刻留空，实际次数不自动填目标。</p>${field('这次补记几组/段','count','number',1,`min="1" max="${remaining}" required`)}`,form=>{const count=M.integer(form.get('count'),99);if(commit(old=>U.backfillBatch(old,{planId:data.plan,day:data.date,itemId:data.item,count,batchId}),'')){modal.close();toast(`已补记${count}${segment(item)}`,btn('undo-batch','撤销本次补记','',`data-batch="${batchId}"`))}},'确认补记')}

function itemMenu(data){const {plan,item}=M.locate(s,data.plan,data.date,data.item);dialog('调整当前动作',`<p><strong>${esc(item.name)}</strong></p><p class="muted small">只修改后续目标，已有记录保留当时快照。</p><div class="fields spaced">${field('目标'+segment(item)+'数','sets','number',item.targetSets,'min="1" max="99"')}${field('每'+segment(item)+(item.side==='each'?'每侧':'')+(item.unit==='seconds'?'时长（秒）':'次数'),'value','number',item.targetValue,'min="1"')}</div>${plan.status==='active'?btn('stop-item','结束此动作剩余安排','danger',`data-plan="${data.plan}" data-date="${data.date}" data-item="${item.id}"`):''}`,form=>{const p=M.clone(plan),i=p.days.find(d=>d.date===data.date).items.find(i=>i.id===item.id);i.targetSets=M.integer(form.get('sets'),99,'组数');i.targetValue=M.integer(form.get('value'),i.unit==='seconds'?3600:999,'目标');if(commit(old=>M.savePlan(old,p),'目标已更新'))modal.close()})}
async function fileData(file){if(!file?.size)return null;if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('请选择PNG、JPEG或WebP图片');if(file.size>U.MAX_IMAGE_BYTES)throw Error('原型个人图片请小于3MB');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('图片读取失败'));reader.readAsDataURL(file)})}
function customDialog(id='',copy=false,options={}){
  const original=id?get(id):null,[scopeKind,scopeId]=(options.scope??'').split(':'),editing=!!original?.custom&&!copy;
  const exercise=original??{name:'',purpose:scopeKind==='purpose'?scopeId:'strength',unit:scopeId==='cardio'||scopeId==='stretch'?'seconds':'reps',side:'total',primaryPart:scopeKind==='part'?scopeId:'',equipment:[['floor']],intro:'',steps:[],cues:[],aliases:[],secondaryParts:[]};
  const references=original?s.plans.flatMap(plan=>plan.days.flatMap(day=>day.items)).filter(item=>item.exerciseId===original.id&&item.status==='active').length:0,history=original?s.events.filter(event=>event.exerciseId===original.id).length:0;
  dialog(editing?'编辑我的动作':copy?'复制为我的动作':'新建我的动作',`${references||history?notice(`已有${references}个安排和${history}条历史引用。名称、计量和目标快照保留，教学页使用当前说明；变更供以后新增时使用。`):''}${field('动作名称','name','text',copy?exercise.name+'（我的版本）':exercise.name,'maxlength="60" required')}<div class="fields"><div class="field"><label for="custom-purpose">活动用途</label><select id="custom-purpose" name="purpose">${Object.entries(PURPOSES).map(([key,label])=>`<option value="${key}" ${exercise.purpose===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="custom-part">主要练哪里</label><select id="custom-part" name="part" ${exercise.purpose!=='strength'?'disabled':''}><option value="">选择一个主要部位</option>${Object.entries(PARTS).map(([key,label])=>`<option value="${key}" ${exercise.primaryPart===key?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="fields"><div class="field"><label for="custom-unit">怎么记录</label><select id="custom-unit" name="unit"><option value="reps" ${exercise.unit==='reps'?'selected':''}>次数</option><option value="seconds" ${exercise.unit==='seconds'?'selected':''}>时长（秒）</option></select></div><div class="field"><label for="custom-side">左右计量</label><select id="custom-side" name="side"><option value="total" ${exercise.side==='total'?'selected':''}>整体完成</option><option value="each" ${exercise.side==='each'?'selected':''}>每侧分别完成</option></select></div></div><div class="field"><label>必需器械（全部具备）</label><div class="check-grid">${Object.entries(EQUIPMENT).map(([key,label])=>`<label><input name="equipment" type="checkbox" value="${key}" ${exercise.equipment[0].includes(key)?'checked':''}>${label}</label>`).join('')}</div></div><details class="custom-extra"><summary>补充简介、步骤、别名和图片（可选）</summary><div class="field spaced"><label for="custom-intro">简介</label><textarea id="custom-intro" name="intro">${esc(exercise.intro)}</textarea></div><div class="field"><label for="custom-steps">动作步骤（每行一步）</label><textarea id="custom-steps" name="steps">${esc(exercise.steps.join('\n'))}</textarea></div>${field('别名（逗号分隔）','aliases','text',(exercise.aliases??[]).join('，'))}<div class="field"><label for="custom-image">个人图片（可选，PNG/JPEG/WebP，最多3 MiB）</label><input id="custom-image" name="image" type="file" accept="image/png,image/jpeg,image/webp">${editing&&exercise.image?`<img class="photo-preview" src="${esc(exercise.image)}" alt="现有个人图片"><label><input type="checkbox" name="removeImage">移除现有图片</label>`:''}<small class="muted">无图也能安排和记组。复制内置动作会带入文字和参数，图片可另选。</small></div></details>`,async form=>{
    const name=String(form.get('name')).trim(),purpose=form.get('purpose'),part=purpose==='strength'?form.get('part'):null,equipment=form.getAll('equipment');
    if(!name||name.length>60)throw Error('动作名须为1—60字符');if(purpose==='strength'&&!part)throw Error('请选择一个主要训练部位');if(!equipment.length)throw Error('请选择必需器械，徒手动作可选地面空间');
    const photo=await fileData(form.get('image'));if(photo)await validatePhotos({customExercises:[{name,image:photo}]});
    const updated={...M.clone(exercise),id:editing?exercise.id:M.uid(),name,purpose,allowedPurposes:[purpose],primaryPart:part,secondaryParts:editing?exercise.secondaryParts:[],unit:form.get('unit'),side:form.get('side'),equipment:[equipment],intro:String(form.get('intro')).trim()||'个人动作，暂无简介。',steps:String(form.get('steps')).split('\n').map(value=>value.trim()).filter(Boolean),cues:editing?exercise.cues:[],aliases:String(form.get('aliases')).split(/[，,\n]/).map(value=>value.trim()).filter(Boolean),english:'',image:form.get('removeImage')?'':photo??(editing?exercise.image:''),custom:true,archived:editing?exercise.archived:false,contentRevision:'personal-'+Date.now(),status:'draft',source:'用户自建动作及个人图片，未经过系统教学审校。',references:[]};
    const next=M.clone(s),index=next.customExercises.findIndex(item=>item.id===updated.id);if(index<0)next.customExercises.push(updated);else next.customExercises[index]=updated;
    let nextEditor=null;if(options.addToDay&&editor){nextEditor=M.clone(editor);M.addItemToDay(nextEditor.plan.days.find(day=>day.date===editor.date),updated,'','');nextEditor.savedAt=new Date().toISOString();next.editorDraft=M.clone(nextEditor)}
    persist(next);if(nextEditor)editor=nextEditor;modal.close();render();toast(nextEditor?`已加入${dateText(editor.date)}，可在查看已选中找到`:'我的动作已保存，已有安排与历史快照保留');
  },options.addToDay?`保存并加入${dateText(editor.date)}`:'保存动作');
}

function addToPlan(id){if(get(id)?.archived){toast('该动作已停用，已有安排保留；可在管理中恢复后再新增。');return}const plans=s.plans.filter(plan=>plan.status==='active');if(!plans.length){startEditor(null,s.demoToday,{single:true,source:'action',step:1,exerciseId:id});return}const chosen=plans.find(plan=>s.demoToday>=plan.start&&s.demoToday<=plan.end)??plans[0],date=s.demoToday>=chosen.start&&s.demoToday<=chosen.end?s.demoToday:chosen.start;dialog('加入计划中的哪一天',`<div class="field"><label for="add-plan">计划</label><select id="add-plan" name="plan">${plans.map(plan=>`<option value="${plan.id}" ${plan.id===chosen.id?'selected':''}>${esc(plan.name)}</option>`).join('')}</select></div><div class="field"><label for="add-date">训练日期</label><input id="add-date" name="date" type="date" value="${date}" min="${chosen.start}" max="${chosen.end}" required></div><p id="add-plan-status" class="notice"></p>${field('目标组/段数','sets','number','','min="1" max="99" required')}${field('每组'+(get(id).side==='each'?'每侧':'')+(get(id).unit==='seconds'?'时长（秒）':'次数'),'value','number','','min="1" required')}`,form=>{const plan=M.clone(plans.find(plan=>plan.id===form.get('plan'))),date=form.get('date');if(!M.calendarDay(date)||date<plan.start||date>plan.end)throw Error('请选择计划范围内的有效日期');const day=plan.days.find(day=>day.date===date);if(!day)throw Error('请先配置该日期');const existing=day.items.find(item=>item.exerciseId===id);if(existing?.status==='active'){modal.close();nav('plan',{planId:plan.id,selected:date});toast('当天已有该动作，已打开原安排');return}M.addItemToDay(day,get(id),existing?existing.targetSets:M.integer(form.get('sets'),99),existing?existing.targetValue:M.integer(form.get('value'),get(id).unit==='seconds'?3600:999));if(commit(old=>M.savePlan(old,plan),existing?'已恢复原条目、目标和进度':'动作已加入所选日期'))modal.close()},'加入或查看安排');modal.dataset.exerciseId=id;updateAddPlanContext()}

function sourcesDialog(){dialog('内容来源与验证范围',`<div class="inspection"><strong>250个候选 · 16个原型样稿 · 0个专业审核通过</strong><br>图片为本项目AI生成的双帧样稿，已经进入本地原型；并不代表标准动作审核完成。肌肉图层来自wger公开SVG，原始人体作者Termininja，CC BY-SA 3.0。细分映射及改作链仍待发布审核。</div><ul class="source-links spaced"><li><a href="https://commons.wikimedia.org/wiki/File:Muscular_system.svg" target="_blank" rel="noreferrer">正面肌肉底图 · Termininja</a></li><li><a href="https://commons.wikimedia.org/wiki/File:Muscular_system-back.svg" target="_blank" rel="noreferrer">背面肌肉底图 · Termininja</a></li><li><a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noreferrer">CC BY-SA 3.0 许可</a></li><li><a href="https://github.com/wger-project/wger" target="_blank" rel="noreferrer">wger肌群图层与API字典</a></li></ul><p class="muted small">已验证：原型规则和页面交互。待验证：正式Android/Room、真实APK体积、图片教学审校、媒体恢复、肩部细分和前臂图层。原型未加入动图，使用静态双帧。</p>`)}
function download(filename,text){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function importDialog(){dialog('备份预检与恢复',`<p class="muted small">这是本地原型JSON备份，恢复会替换此原型健身资料。正式Android媒体包另行验证。</p><div class="field spaced"><label>选择原型备份</label><input id="backup-file" type="file" accept="application/json,.json"></div><div id="backup-inspection" class="muted small">先选择文件并进行预检。</div><div class="modal-actions">${btn('inspect-import','预检文件','primary')}</div>`)}
let modalState={dirty:false,save:false,submitting:false};
function requestCloseModal(){if(modalState.submitting)return;if(modalState.dirty&&modalState.save){if(!modal.querySelector('.exit-warning'))modal.querySelector('form').insertAdjacentHTML('beforeend',`<div class="notice warning exit-warning" role="alert"><div>当前填写尚未保存。${btn('modal-keep','继续填写','secondary')}${btn('modal-discard','放弃修改','danger')}</div></div>`);return}mediaJob++;modal.close()}
function planReview(plan){const issues=U.planIssues(plan,s);return `<h2>检查每日安排</h2><p class="muted small spaced">${esc(plan.name)} · ${plan.start} — ${plan.end}</p><div class="chips spaced">${['training','rest','unplanned'].map(kind=>`<span class="tag gray">${{training:'训练',rest:'休息',unplanned:'未安排'}[kind]} ${plan.days.filter(day=>day.kind===kind).length}天</span>`).join('')}<span class="tag ${issues.length?'sand':''}">待补 ${new Set(issues.filter(issue=>issue.day).map(issue=>issue.day)).size}天</span></div><section class="review-checklist spaced"><h3>${issues.length?`还有${issues.length}处待补`:'安排已齐全，可保存'}</h3>${issues.map((issue,index)=>`<div class="record-row"><span class="row-copy">${esc(issue.message)}</span>${btn('go-issue',issue.field==='pick'?'去选择':'去填写','link',`data-index="${index}"`)}</div>`).join('')}</section>${plan.days.map(day=>`<details class="overview-day" ${plan.days.length<=7||issues.some(issue=>issue.day===day.date)?'open':''}><summary>${day.date} · ${day.kind==='training'?partNames(day.parts)||'活动训练':day.kind==='rest'?'休息':'未安排（允许保留）'}</summary>${P.activeItems(day).map(item=>`<p>${esc(item.name)}　${item.targetSets||'待填'}${segment(item)} × ${item.side==='each'?'每侧':''}${item.targetValue||'待填'}${units(item)}</p>`).join('')}${btn('review-day','编辑这一天','link',`data-date="${day.date}"`)}</details>`).join('')}${notice('保存后才生效；未安排与休息日不会自动生成训练记录。')}`}
function goIssue(index){const issue=U.planIssues(editor.plan,s)[Number(index)];if(!issue)return;if(issue.day)editor.date=issue.day;editor.step=['name','dates'].includes(issue.field)?0:issue.day?2:1;saveEditorDraft();render();if(issue.field==='pick'){openPicker(issue.scope);return}const input=issue.itemId?document.querySelector(`[data-target="${issue.field}"][data-id="${issue.itemId}"]`):document.querySelector(issue.field==='name'?'#plan-name':'#plan-start');input?.focus();input?.scrollIntoView({block:'center'})}
function updateAddPlanContext(){const plan=s.plans.find(plan=>plan.id===modal.querySelector('#add-plan')?.value),input=modal.querySelector('#add-date');if(!plan||!input)return;input.min=plan.start;input.max=plan.end;if(input.value<plan.start||input.value>plan.end)input.value=plan.start;const item=plan.days.find(day=>day.date===input.value)?.items.find(item=>item.exerciseId===modal.dataset.exerciseId);const status=modal.querySelector('#add-plan-status');if(status)status.textContent=item?`已存在此动作：${item.targetSets}${segment(item)}×${item.targetValue}${units(item)}。${item.status==='active'?'可直接查看原安排，无需重复添加。':'重新加入会恢复原目标和进度。'}`:'填写本次安排的目标';for(const field of modal.querySelectorAll('input[name=sets],input[name=value]')){field.disabled=!!item;field.required=!item}}
function focusWorkout(itemId){ui.selected=s.demoToday;ui.focusItemId=itemId;render();document.querySelector(`[data-workout="${itemId}"]`)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
function batchDaysDialog(mode){const source=currentEditorDay(),choices=editor.plan.days.filter(day=>mode!=='copy'||day.date!==editor.date);if(!choices.length){dialog('先增加目标日期',`${notice('当前计划只有一天，请先扩大日期范围。')}${btn('edit-plan-range','修改日期范围','primary')}`);return}dialog(mode==='copy'?'复制这一天到多个日期':'批量安排部位',`<p class="muted small">${mode==='copy'?'只复制动作与目标，不复制记录。':'覆盖已有安排会结束其原动作；历史日不能批量覆盖。'}</p><div class="check-grid spaced">${choices.map(day=>{const historical=s.events.some(event=>event.planId===editor.plan.id&&event.day===day.date);return `<label><input name="target-date" type="checkbox" value="${day.date}" ${historical?'disabled':day.kind==='unplanned'?'checked':''}>${day.date} · ${historical?'历史只读':day.kind==='training'?'已有训练':day.kind==='rest'?'已有休息':'未安排'}</label>`}).join('')}</div>${mode==='parts'?`<div class="field spaced"><label for="batch-kind">安排状态</label><select id="batch-kind" name="kind"><option value="training">训练日</option><option value="rest">休息日</option><option value="unplanned">未安排</option></select></div><div class="check-grid">${Object.entries(PARTS).map(([key,label])=>`<label><input name="parts" type="checkbox" value="${key}" ${source.parts.includes(key)?'checked':''}>${label}</label>`).join('')}</div>`:''}<label class="overwrite-option"><input name="overwrite" type="checkbox">允许覆盖所选日期的原安排（无历史）</label>`,form=>{const targets=form.getAll('target-date'),overwrite=form.get('overwrite')==='on';if(!overwrite&&targets.some(date=>editor.plan.days.find(day=>day.date===date)?.kind!=='unplanned'))throw Error('所选日期已有安排，请取消该日或明确允许覆盖');editor.plan=mode==='copy'?U.copyDraftDays(editor.plan,editor.date,targets,s):U.batchDayParts(editor.plan,targets,{kind:form.get('kind'),parts:form.getAll('parts'),overwrite},s);saveEditorDraft();render();modal.close()},'确认应用到所选日期')}
function readOnlyDay(plan,day){return `<section class="card"><h2>当日原安排</h2>${day?.items?.length?day.items.map(item=>`<div class="record-row"><div class="row-copy"><strong>${esc(item.name)}</strong><small>${item.targetSets}${segment(item)} × ${item.side==='each'?'每侧':''}${item.targetValue}${units(item)} · 已记${M.itemEvents(s,item.id).length}${segment(item)}</small></div>${btn('detail','查看教学','link',`data-id="${item.exerciseId}"`)}</div>`).join(''):'<p class="muted">当日没有动作安排。</p>'}<h2 class="spaced">实际训练记录</h2>${eventRows(M.activeEvents(s,{planId:plan.id,start:ui.selected,end:ui.selected}).reverse())}</section>`}
function copySavedDay(){const source=s.plans.find(plan=>plan.id===ui.planId)?.days.find(day=>day.date===ui.selected),plans=s.plans.filter(plan=>plan.status==='active');if(!source||!U.copyableItems(s.plans.find(plan=>plan.id===ui.planId),source).length){toast('这一天没有可复制的动作');return}if(!plans.length){dialog('用原安排创建新计划',`<p>保留原动作与目标，创建一份新的单日草稿；训练记录从0开始。</p>${btn('copy-new-plan','创建单日计划并带入','primary')}`);return}const chosen=plans[0],date=chosen.days.find(day=>day.date>=s.demoToday&&!(chosen.id===ui.planId&&day.date===ui.selected)&&!s.events.some(event=>event.planId===chosen.id&&event.day===day.date))?.date??chosen.start;dialog('复制原安排到哪一天',`<div class="field"><label for="copy-plan">目标生效计划</label><select id="copy-plan" name="plan">${plans.map(plan=>`<option value="${plan.id}">${esc(plan.name)}</option>`).join('')}</select></div>${field('目标日期','date','date',date,`min="${chosen.start}" max="${chosen.end}" required`)}<p class="muted small">仅复制目标，不复制记录。含完成或撤销记录的目标日不能覆盖。</p><label class="overwrite-option"><input name="overwrite" type="checkbox">允许替换目标日已有安排（无历史）</label>`,form=>{const target=s.plans.find(plan=>plan.id===form.get('plan')),date=form.get('date'),day=target?.days.find(day=>day.date===date);if(day?.kind!=='unplanned'&&!form.get('overwrite'))throw Error('目标日已有安排，请明确允许替换');if(commit(old=>U.copyIntoPlan(old,ui.planId,ui.selected,target.id,[date]),'原安排已复制，记录从0开始'))modal.close()})}
function templateDialog(save=false){if(save){dialog('保存个人训练模板',field('模板名称','name','text',partNames(currentEditorDay().parts)||'我的训练','maxlength="60" required')+notice('保存动作和目标；不包含完成记录。'),form=>{if(commit(old=>U.saveTemplate(old,currentEditorDay(),String(form.get('name'))),'个人模板已保存'))modal.close()});return}const templates=s.templates??[];if(!templates.length){dialog('还没有个人模板',notice('先为一天选择动作并填好目标，再保存为模板。'));return}dialog('应用个人训练模板',`<div class="field"><label for="personal-template">选择模板</label><select id="personal-template" name="template">${templates.map(template=>`<option value="${template.id}">${esc(template.name)} · ${template.items.length}个动作</option>`).join('')}</select></div><div id="template-preview" class="notice"></div><label class="overwrite-option"><input type="checkbox" name="overwrite">允许替换当天已有安排（有历史时不能覆盖）</label>`,form=>{const day=currentEditorDay();if((day.kind!=='unplanned'||P.activeItems(day).length)&&!form.get('overwrite'))throw Error('当天已有安排，请明确允许替换');editor.plan=U.applyTemplate(editor.plan,editor.date,templates.find(template=>template.id===form.get('template')),s);saveEditorDraft();render();modal.close()});updateTemplatePreview()}
function updateTemplatePreview(){const template=(s.templates??[]).find(template=>template.id===modal.querySelector('#personal-template')?.value),preview=modal.querySelector('#template-preview');if(preview&&template)preview.textContent=template.items.map(item=>`${item.name} ${item.targetSets}${segment(item)}×${item.side==='each'?'每侧':''}${item.targetValue}${units(item)}`).join('；')}
function recoveryDialog(){const parts=M.schedule(s,s.demoToday).parts,facts=U.recoveryFacts(s,parts.length?parts:[...new Set(M.activeEvents(s,{purpose:'strength'}).slice().reverse().map(event=>event.snapshot.primaryPart))].slice(0,3));dialog('最近训练与一般恢复参考',`<p>${esc(recoveryText())}</p>${facts.map(({part,event})=>`<div class="record-row"><div class="row-copy"><strong>${PARTS[part]}</strong><small>${event?`${event.day} · ${event.snapshot.primaryPart===part?'主练记录':'辅助参与记录'} · ${esc(event.snapshot.name)}${event.timeSource==='dateOnly'?' · 具体时刻未填':''}`:'暂无已记录训练'}</small></div>${event?btn('record-day','查看依据','link',`data-plan="${event.planId}" data-date="${event.day}"`):''}</div>`).join('')}${notice('同一肌群训练需考虑恢复间隔；记录可能不包含全部活动。此处不判定恢复完成，也不自动更改你的计划。')}<a href="https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842" target="_blank" rel="noreferrer">一般力量训练参考来源</a>`)}
function bindPoseImages(root=app){for(const image of root.querySelectorAll('.pose img,.pose image')){const pose=image.closest('.pose'),gallery=pose.closest('[data-gallery]');image.addEventListener('error',()=>{pose.classList.add('failed');gallery?.classList.add('media-error')});image.addEventListener('load',()=>{pose.classList.remove('failed');if(gallery&&!gallery.querySelector('.pose.failed'))gallery.classList.remove('media-error')});if(image.tagName==='IMG'&&image.complete&&!image.naturalWidth){pose.classList.add('failed');gallery?.classList.add('media-error')}}for(const image of root.querySelectorAll('.muscle>img'))image.addEventListener('error',()=>{const muscle=image.closest('.muscle');muscle.classList.add('failed');if(!muscle.querySelector('.part-mark'))muscle.insertAdjacentHTML('beforeend','<span class="part-mark">示意图暂不可用</span>')})}
