  'day-kind':d=>{const day=currentEditorDay();if(d.kind!=='training'&&day.items.some(i=>i.status==='active'))confirm('更改本日安排','将结束当前剩余动作，已有记录保留。',()=>{day.kind=d.kind;day.parts=[];day.items.forEach(i=>i.status='stopped');saveEditorDraft();render()});else {day.kind=d.kind;if(d.kind!=='training')day.parts=[];saveEditorDraft();render()}},
  pick:d=>{const item=currentEditorDay().items.find(i=>i.exerciseId===d.id&&i.status==='active');if(!item&&!M.equipmentMatches(get(d.id),s.preferences.equipment))confirm('此动作缺少部分器械','请先确认具备动作的全部必需器械。保留此动作不会修改我的器械偏好。',()=>{pick(d.id)});else pick(d.id)},'pick-detail':d=>{const selected=P.activeItems(currentEditorDay()).some(item=>item.exerciseId===d.id),choose=()=>{if(!selected)pick(d.id);back()};if(!selected&&!M.equipmentMatches(get(d.id),s.preferences.equipment))confirm('此动作缺少部分器械','请确认具备此动作全部必需器械后加入。',choose);else choose()},'review-day':d=>{editor.date=d.date;editorStep(2)},
  'editor-remove':d=>removeEditorItem(d.id),
  reorder:d=>{replaceEditorDay(P.reorder(currentEditorDay(),d.id,d.direction));saveEditorDraft();repaintPicker()},
  'batch-targets':d=>batchTargetsDialog(d.scope??'all'),
  'open-picker':d=>openPicker(d.scope),'picker-scope':d=>changePickerScope(d.scope),
