  'picker-selected':()=>{rememberPickerScroll();ui.picker={...ui.picker,view:ui.picker.view==='selected'?'all':'selected'};storePicker();render();window.scrollTo(0,ui.picker.view==='selected'?0:pickerView().scroll??0)},
  'copy-editor-day':()=>batchDaysDialog('copy'),
