  'custom-range':()=>dialog('自定义统计范围',`<div class="fields">${field('开始日期','start','date',ui.statsStart)}${field('结束日期','end','date',ui.statsEnd)}</div><small class="muted">包含首尾；结束日期不晚于演示中的今天。</small>`,form=>{M.dates(form.get('start'),form.get('end'));if(form.get('end')>s.demoToday)throw Error('统计不能选择未来日期');ui.statsDays=0;ui.statsStart=form.get('start');ui.statsEnd=form.get('end');render();modal.close()},'查看统计'),
  'stats-by':d=>{ui.statsBy=d.by;render()},'stat-detail':d=>{const events=M.activeEvents(s,{start:ui.statsStart,end:ui.statsEnd,planId:ui.statsPlan,purpose:ui.statsPurpose}).filter(e=>ui.statsBy==='exercise'?e.exerciseId===d.key&&e.snapshot.unit===d.unit&&e.snapshot.side===d.side:(e.snapshot.primaryPart??e.snapshot.purpose)===d.key);dialog('组成这项统计的记录',eventRows(events.slice().reverse()))},
  'streak-info':()=>dialog('连续训练怎样计算',`<p>至少有一条有效力量/有氧记录的自然日算训练日。同一天多个计划只算一天；单独热身或拉伸不计。</p><p class="muted spaced">今天未练时暂显示截至昨天的连续值。无训练的休息日会中断自然日连续，这不代表休息是不好的。</p>`),
  'parts-info':()=>{const q=M.schedule(s,s.demoToday),actual=[...new Set(q.actual.filter(e=>e.snapshot.purpose==='strength').map(e=>e.snapshot.primaryPart))];dialog('今天安排与已练部位',`<p><strong>计划主部位：</strong>${partNames(q.parts)||'无力量部位安排'}</p><p class="spaced"><strong>已练主部位：</strong>${partNames(actual)||'暂无力量记录'}</p>${notice('已练表示至少确认一组，不代表该部位全部目标已完成。辅助参与不自动填满主部位进度。')}`)},
  recovery:()=>recoveryDialog(),
  custom:d=>customDialog(d.id??''),'copy-custom':d=>customDialog(d.id,true),'toggle-custom':d=>{const e=get(d.id);const references=s.plans.flatMap(p=>p.days.flatMap(day=>day.items)).filter(i=>i.exerciseId===d.id&&i.status==='active').length;confirm(e.archived?'恢复动作选择':'停用我的动作',`已有${references}个有效安排引用；停用后不再出现在新动作选择，已有安排和历史仍保留。`,()=>commit(old=>{const n=M.clone(old),e=n.customExercises.find(e=>e.id===d.id);e.archived=!e.archived;return n},'动作状态已更新'))},
